import{_ as e,c as t,o as a,ah as i}from"./chunks/framework.BnWtW52D.js";const g=JSON.parse('{"title":"教程：安装光影包","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"helps/shader.md","filePath":"helps/shader.md"}'),o={name:"helps/shader.md"};function s(l,r,n,d,c,h){return a(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="教程-安装光影包" tabindex="-1">教程：安装光影包 <a class="header-anchor" href="#教程-安装光影包" aria-label="Permalink to “教程：安装光影包”">​</a></h1><p>为 Minecraft 安装光影包，可以大幅提升游戏的视觉效果，让方块世界拥有更真实的光影、水面反射和动态阴影。本文将详细介绍光影包的类型、所需模组以及具体的安装步骤。</p><h2 id="光影包分类" tabindex="-1">光影包分类 <a class="header-anchor" href="#光影包分类" aria-label="Permalink to “光影包分类”">​</a></h2><p>在开始安装前，需要先了解光影包的两种主要格式，它们的使用方式有所不同。</p><h3 id="普通光影包" tabindex="-1">普通光影包 <a class="header-anchor" href="#普通光影包" aria-label="Permalink to “普通光影包”">​</a></h3><p>大多数光影包使用的格式，文件通常以 <code>.zip</code> 结尾。这种光影包<strong>需要</strong>借助光影加载器（如 Iris、Oculus 或 OptiFine）才能加载。这也是本文主要讲解的安装方式。</p><h3 id="着色器资源包" tabindex="-1">着色器资源包 <a class="header-anchor" href="#着色器资源包" aria-label="Permalink to “着色器资源包”">​</a></h3><p>这是一种特殊的格式，可以被原版 Minecraft 直接作为资源包加载，<strong>无需</strong>安装任何光影加载器。如果您下载的光影包属于这种格式，直接将光影包放入资源包文件夹并加载即可，无需继续阅读本文章。</p><h2 id="shader-loader" tabindex="-1">光影加载器 <a class="header-anchor" href="#shader-loader" aria-label="Permalink to “光影加载器”">​</a></h2><p>要加载普通光影包，需要先安装一个光影加载器。根据您使用的模组加载器不同，推荐的选择也有所不同。</p><table tabindex="0"><thead><tr><th>模组加载器</th><th>推荐光影加载器</th><th>备选光影加载器</th></tr></thead><tbody><tr><td>Fabric</td><td>Iris（需要 Sodium）</td><td>OptiFine（需 OptiFabric）</td></tr><tr><td>Forge</td><td>Oculus（需 Embeddium 或 Rubidium）</td><td>OptiFine</td></tr><tr><td>NeoForge</td><td>Iris（1.21.11 以下需要 Sodium）</td><td>Oculus 或 OptiFine</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>OptiFine 在高版本 Minecraft 下的稳定性和兼容性较差，容易与其他模组冲突，不推荐使用。建议优先选择 Iris 或 Oculus。</p></div><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to “安装步骤”">​</a></h2><p>以下内容假设您已经安装好了启动器、游戏实例和模组加载器（Fabric、Forge 或 NeoForge）。</p><h3 id="_1-安装光影加载器" tabindex="-1">1. 安装光影加载器 <a class="header-anchor" href="#_1-安装光影加载器" aria-label="Permalink to “1. 安装光影加载器”">​</a></h3><p>根据上方的表格，选择对应您模组加载器的光影加载器进行安装。</p><p><strong>如果您的启动器支持模组安装功能，直接在启动器的模组管理界面搜索并安装即可</strong>，以下介绍的是手动安装方式。</p><ul><li><p><strong>若使用 Iris（Fabric / NeoForge）</strong>：</p><ol><li>访问 Iris Shaders 官网，下载对应 Minecraft 版本的安装程序。</li><li>运行安装程序，选择目标游戏实例进行安装。</li><li>安装程序会自动下载并配置所需的 Sodium 等前置模组。</li></ol><p>详细指引：<a href="https://github.com/IrisShaders/Iris/blob/1.20.3/docs/guide.md#for-standalone-use" target="_blank" rel="noreferrer">Iris installation and usage guide</a>（英文）</p></li><li><p><strong>若使用 Oculus（Forge）</strong>：</p><ol><li>访问 Modrinth 或 CurseForge 等网站，搜索并下载对应 Minecraft 版本的 Oculus 和 Embeddium（1.20.1 及以上）或 Rubidium（1.20.1 以下）。</li><li>将下载的模组文件（<code>.jar</code>）放入游戏目录的 <code>mods</code> 文件夹中。</li></ol></li><li><p><strong>若使用 OptiFine（不推荐）</strong>：</p><ol><li>访问 OptiFine 官网，下载对应版本的安装程序。</li><li>直接运行安装程序，将其安装为独立的游戏版本；或使用 OptiFabric 将其与 Fabric 配合使用。</li></ol></li></ul><h3 id="_2-下载光影包" tabindex="-1">2. 下载光影包 <a class="header-anchor" href="#_2-下载光影包" aria-label="Permalink to “2. 下载光影包”">​</a></h3><p>光影包可在各大 Minecraft 资源网站获取，如：</p><ul><li><a href="https://modrinth.com/discover/shaders" target="_blank" rel="noreferrer"><strong>Modrinth</strong></a></li><li><a href="https://www.curseforge.com/minecraft/search?class=shaders" target="_blank" rel="noreferrer"><strong>CurseForge</strong></a></li><li><strong>Shader Labs</strong> 等社区论坛</li></ul><p><strong>下载方法（以 Modrinth 为例）</strong>：</p><ol><li>在光影包详情页找到右侧的 <strong>“Download”</strong> 按钮并点击。</li><li>选择与您光影加载器对应的版本（通常标注有 <strong>Iris</strong> 或 <strong>OptiFine</strong> 标签）。</li><li>下载得到的文件通常是 <code>.zip</code> 格式，<strong>无需解压</strong>。</li></ol><p>大部分<strong>第三方启动器</strong>也内置了光影下载功能，可以自动下载并将光影包放入正确位置，<strong>无需手动执行下方的第 3 步</strong>。</p><h3 id="_3-放入光影包文件夹" tabindex="-1">3. 放入光影包文件夹 <a class="header-anchor" href="#_3-放入光影包文件夹" aria-label="Permalink to “3. 放入光影包文件夹”">​</a></h3><p>完成光影加载器的安装后，需要将下载的光影包放入指定位置。</p><p><strong>方法一：通过游戏内界面（推荐）</strong></p><ol><li>启动 Minecraft，进入游戏主菜单。</li><li>点击 <strong>选项</strong> → <strong>视频设置</strong> → <strong>光影</strong>（或 <strong>Shaders</strong>，具体名称可能因光影加载器而异）。</li><li>将下载的光影包（<code>.zip</code> 文件）拖入 Minecraft 窗口。</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>部分光影加载器可能不支持通过拖拽添加光影包，如果拖拽后没有反应，请使用手动放置的方式（方法二）。</p></div><p><strong>方法二：手动放入文件夹</strong></p><p>将光影包文件（<code>.zip</code>）放入位于游戏目录下的光影包文件夹（<code>shaderpacks</code>）即可。<br> 如果该文件夹不存在，可以手动创建一个。</p><p>至此，您已成功为 Minecraft 安装并启用了光影包。尽情享受焕然一新的视觉体验吧！</p>',32)])])}const b=e(o,[["render",s]]);export{g as __pageData,b as default};
